const query = ($input.item.json.query || '').trim();
const sessionId = $input.item.json.sessionId || '';

return {
  query: query,
  sessionId: sessionId,
  queryLower: query.toLowerCase()
};

// 规则引擎意图分类
const q = $input.item.json.queryLower;
const query = $input.item.json.query;

let intent = 'search';
let params = {};

// 1. 推荐类: "推荐" + 书名
const recommendMatch = query.match(/(?:推荐|类似|相似|像).*?[《](.+?)[》]/);
if (recommendMatch || /(?:推荐|类似|相似).*?(?:的书|小说|作品|图书)/.test(q)) {
  intent = 'recommend';
  if (recommendMatch) params.bookName = recommendMatch[1];
}
// 2. 详情查询: "《XXX》" 的书架/评分/信息
else if (/[《](.+?)[》]/.test(query) && /(?:在哪|书架|详情|信息|评分|简介)/.test(q)) {
  intent = 'detail';
  const m = query.match(/[《](.+?)[》]/);
  if (m) params.bookName = m[1];
}
// 3. 帮助类
else if (/^(?:你好|hi|hello|帮助|help|你能|功能)/i.test(q) || q.length < 2) {
  intent = 'help';
}
// 4. 最近/新书
else if (/(?:最近|新书|刚.*(?:买|加|添)).*(?:书|哪些|什么)/.test(q)) {
  intent = 'search';
  params.timeFilter = 'recent';
}
// 5. 评分相关
else if (/(?:评分|高分|好评|几星).*(?:书|最高|推荐)/.test(q)) {
  intent = 'search';
  params.ratingFilter = true;
}
// 6. 默认搜索
else {
  intent = 'search';
}

return {
  intent: intent,
  query: query,
  params: params,
  sessionId: $input.item.json.sessionId
};

return {
  url: 'http://localhost:8000/api/chat/search',
  method: 'POST',
  body: { query: $input.item.json.query, limit: 10 }
};

const resp = $input.item.json;
const results = resp.results || [];
const total = resp.total || results.length;
const understanding = resp.query_understanding || '';

if (results.length === 0) {
  return {
    reply: `🔍 未找到匹配的图书\n\n我在馆藏 102 本书中没有找到与"${$('code-classify').item.json.query}"匹配的结果。\n\n建议：\n• 尝试用不同的关键词描述（如作者名、出版社、主题等）\n• 用 ISBN 精确查找\n• 在"智能录入"页面同步新书信息`
  };
}

let reply = `📚 找到 **${total}** 本相关图书\n`;
if (understanding) reply += `> ${understanding}\n`;
reply += '\n';

const top5 = results.slice(0, 5);
for (let i = 0; i < top5.length; i++) {
  const b = top5[i];
  reply += `**${i + 1}. 《${b.title || '未知书名'}》**\n`;
  if (b.author) reply += `   ✍️ ${b.author}`;
  if (b.publisher) reply += ` | ${b.publisher}`;
  if (b.rating) reply += ` | ⭐ ${b.rating}`;
  reply += '\n';
  if (b.shelf_names && b.shelf_names.length > 0) reply += `   📍 书架：${b.shelf_names.join('、')}\n`;
  if (b.summary) reply += `   📖 ${b.summary.substring(0, 100)}${b.summary.length > 100 ? '...' : ''}\n`;
  reply += '\n';
}

if (results.length > 5) {
  reply += `... 还有 ${results.length - 5} 本相关图书`;
}

return { reply: reply };

// 先搜索找到书名匹配的 book_id
const bookName = $input.item.json.params.bookName || '';
const query = $input.item.json.query;

// 提取书名关键词用于搜索
let searchQuery = bookName;
if (!searchQuery) {
  // 从查询中提取可用于搜索的关键词
  const m = query.match(/(?:推荐|类似|相似|像)(.+?)(?:的书|小说|作品|图书|$)/);
  searchQuery = m ? m[1].trim() : query;
}

return {
  step: 'find_book',
  url: 'http://localhost:8000/api/chat/search',
  method: 'POST',
  body: { query: searchQuery, limit: 3 },
  originalQuery: query
};

const resp = $input.item.json;
const results = resp.results || [];

if (results.length === 0) {
  return {
    reply: `🔍 未在馆藏中找到匹配的图书\n\n建议：\n• 确认书名是否正确\n• 尝试用作者名或其他关键词描述`,
    skip: true
  };
}

const first = results[0];
return {
  step: 'get_similar',
  url: `http://localhost:8000/api/chat/book/${first.book_id}/similar`,
  method: 'GET',
  bookName: first.title,
  bookId: first.book_id
};

const resp = $input.item.json;
const similar = resp.similar_books || resp.results || [];
const bookName = $('code-get-book-id').item.json.bookName || '';

if (similar.length === 0) {
  return {
    reply: `📚 《${bookName}》是馆藏中独一无二的一本！\n\n虽然没有找到相似的图书，但你可以尝试：\n• 用作者名搜索："${bookName} 的作者"\n• 浏览封面墙发现更多好书`
  };
}

let reply = `📚 基于《${bookName}》的推荐\n\n`;

for (let i = 0; i < Math.min(similar.length, 5); i++) {
  const b = similar[i];
  const reasons = [];
  if (b.match_reason) reasons.push(b.match_reason);
  const reasonText = reasons.length > 0 ? `（${reasons.join('、')}）` : '';

  reply += `**${i + 1}. 《${b.title || '未知书名'}》** ${reasonText}\n`;
  if (b.author) reply += `   ✍️ ${b.author}`;
  if (b.publisher) reply += ` | ${b.publisher}`;
  if (b.rating) reply += ` | ⭐ ${b.rating}`;
  reply += '\n';
  if (b.shelf_names && b.shelf_names.length > 0) reply += `   📍 ${b.shelf_names.join('、')}\n`;
  reply += '\n';
}

return { reply: reply };

const bookName = $input.item.json.params.bookName || '';

if (!bookName) {
  return { reply: '请告诉我你想查看哪本书的详情，例如："《三体》在哪个书架？"', skip: true };
}

return {
  step: 'find_book',
  url: 'http://localhost:8000/api/chat/search',
  method: 'POST',
  body: { query: bookName, limit: 1 },
  bookName: bookName
};

const resp = $input.item.json;
const results = $('http-search-detail').item.json.results || [];

if (results.length === 0) {
  return {
    reply: `🔍 未在馆藏中找到该书\n\n建议确认书名是否正确，或尝试用作者名搜索。`
  };
}

const first = results[0];
// 如果 get_detail 返回了更详细的信息则使用
const detail = (resp && resp.book_id) ? resp : first;

let reply = `📖 **《${detail.title || first.title}》**\n\n`;
if (detail.author) reply += `✍️ 作者：${detail.author}\n`;
if (detail.isbn) reply += `🔢 ISBN：${detail.isbn}\n`;
if (detail.publisher) reply += `🏢 出版社：${detail.publisher}\n`;
if (detail.publish_date) reply += `📅 出版日期：${detail.publish_date}\n`;
if (detail.pages) reply += `📄 页数：${detail.pages}\n`;
if (detail.price) reply += `💰 定价：${detail.price}\n`;
if (detail.binding) reply += `📚 装帧：${detail.binding}\n`;
if (detail.series) reply += `📂 丛书：${detail.series}\n`;
if (detail.translator) reply += `🖊 译者：${detail.translator}\n`;
if (detail.original_title) reply += `🌐 原作名：${detail.original_title}\n`;
if (detail.rating) reply += `⭐ 豆瓣评分：${detail.rating}/10\n`;

// 书架信息
const shelves = detail.shelves || [];
if (shelves.length > 0) {
  reply += '\n📍 **所在书架**\n';
  for (const s of shelves) {
    reply += `• ${s.shelf_name}`;
    if (s.physical_location) reply += ` (${s.physical_location})`;
    reply += '\n';
  }
}

if (detail.summary) {
  reply += `\n📖 **内容简介**\n${detail.summary.substring(0, 300)}${detail.summary.length > 300 ? '...' : ''}\n`;
}

if (detail.source) reply += `\n📡 数据来源：${detail.source}`;

return { reply: reply };

// 检查推荐分支是否已跳过（未找到目标书）
const recommendResult = $items('代码-格式化推荐结果');
if (recommendResult && recommendResult.length > 0) {
  const item = recommendResult[0];
  if (item.json && item.json.skip) {
    // 推荐失败 → 回退为普通搜索
    return {
      fallbackSearch: true,
      url: 'http://localhost:8000/api/chat/search',
      method: 'POST',
      body: { query: $('代码-准备推荐请求').item.json.originalQuery || $('代码-准备推荐请求').item.json.query, limit: 5 }
    };
  }
}
return { fallbackSearch: false };

// 汇总所有分支的 reply
const items = $input.all();
for (const item of items) {
  if (item.json && item.json.reply && !item.json.skip) {
    return { reply: item.json.reply };
  }
}
return { reply: '收到你的消息。请尝试：\n• 用书名、作者或主题描述搜索\n• "推荐类似《XXX》的书" 获取推荐\n• 输入书名查看详情和所在书架' };
